<style>
/* Satu desain KIA untuk profil, halaman digital, dan cetak. */
.kia-unified-card{width:100%;aspect-ratio:85.6/54;position:relative;box-sizing:border-box;overflow:hidden;border:1px solid #d7d4bc;border-radius:18px;background:#edf4e9;color:#173c2e;box-shadow:0 5px 0 #b49a5c,0 15px 34px #183c2f15;font-family:'DM Sans',Arial,sans-serif;container-type:inline-size;text-align:left}
.kia-unified-card *{box-sizing:border-box}
.kia-unified-card::before{content:'';position:absolute;inset:1.2%;border:1px solid #cfbf91;border-radius:13px;pointer-events:none}
.kia-unified-inner{position:relative;height:100%;padding:4.2% 5% 3.7%;display:flex;flex-direction:column}
.kia-unified-heading{display:flex;align-items:center;justify-content:space-between;gap:2%}
.kia-unified-heading h3{font-family:Georgia,'Times New Roman',serif;font-size:5.2cqw;line-height:1.05;font-weight:700;color:#173f30;margin:0}
.kia-unified-heading p{font-size:1.8cqw;line-height:1.3;color:#698073;margin:.6cqw 0 0}
.kia-unified-star{font-size:3.8cqw;color:#ac9056;line-height:1}
.kia-unified-divider{margin:3% 0 3%;height:1px;background:#cbd7c8;flex-shrink:0}
.kia-unified-main{display:flex;align-items:center;gap:5%;flex:1;min-height:0}
.kia-unified-photo{width:25%;aspect-ratio:3/4;max-height:100%;overflow:hidden;border:1px solid #c5d1c2;border-radius:9px;background:#dce9dc;display:grid;place-items:center;flex-shrink:0;color:#46735a;font-family:Georgia,serif;font-size:13cqw;font-weight:700}
.kia-unified-photo img{display:block;width:100%;height:100%;object-fit:cover;object-position:center 25%}
.kia-unified-fields{min-width:0;flex:1;display:grid;align-content:center;gap:1cqw}
.kia-unified-fields span{font-size:1.7cqw;font-weight:750;text-transform:uppercase;color:#758d7c;line-height:1.1}
.kia-unified-fields strong{font-size:2.75cqw;font-weight:800;color:#173d2e;line-height:1.14;overflow-wrap:anywhere;margin-bottom:1cqw}
.kia-unified-fields .kia-unified-number{font-size:2.85cqw;letter-spacing:.01em}
.kia-unified-footer{display:flex;align-items:center;justify-content:space-between;gap:3%;margin-top:3.5%;padding-top:3%;border-top:1px solid #cad7c9;font-size:1.65cqw;font-weight:800;text-transform:uppercase;color:#718b76;line-height:1.2}
.kia-unified-back-center{flex:1;display:flex;flex-direction:column;justify-content:center;align-items:center;text-align:center;gap:2.1cqw}
.kia-unified-back-mark{font:700 5.5cqw Georgia,serif;color:#193e31}
.kia-unified-back-center h4{font-size:4.1cqw;line-height:1.1;letter-spacing:.01em;margin:0;color:#173d2e}
.kia-unified-back-center p{font-size:2cqw;line-height:1.5;max-width:76%;margin:0;color:#59705e}
.kia-unified-back-nia{font-size:2.7cqw;font-weight:800;letter-spacing:.04em;color:#173d2e}
.kia-unified-card a{color:inherit}
@supports not (font-size:1cqw){.kia-unified-heading h3{font-size:24px}.kia-unified-heading p{font-size:9px}.kia-unified-fields span{font-size:8px}.kia-unified-fields strong{font-size:13px}.kia-unified-fields .kia-unified-number{font-size:13px}.kia-unified-footer{font-size:8px}.kia-unified-star{font-size:18px}}
@media print{.kia-unified-card{width:85.6mm!important;height:54mm!important;aspect-ratio:auto!important;border-radius:2mm!important;box-shadow:0 .8mm 0 #b49a5c!important;-webkit-print-color-adjust:exact;print-color-adjust:exact;break-inside:avoid}.kia-unified-card::before{border-radius:1.5mm}.kia-unified-photo{border-radius:1mm}}
</style>
